class Model:
    def __init__(self, name):
        self.name = name
        self.calls = 0

    def predict(self, x):
        self.calls += 1
        return x * 2

m = Model("toy")
print(m.predict(3), m.calls)
print(type(m).__name__, isinstance(m, Model))

class Base:
    kind = "base"            # class variable: sab objects share karte hain

    def describe(self):
        return f"{self.kind}:{type(self).__name__}"

class Cached(Base):
    kind = "cached"

    def describe(self):
        return "cached -> " + super().describe()

c = Cached()
print(c.describe())
print(Base().describe())
print(c.kind, Base.kind)

from dataclasses import dataclass, field

@dataclass
class Run:
    name: str
    tags: list = field(default_factory=list)

    @property
    def label(self) -> str:
        return self.name.upper()

r1, r2 = Run("eval"), Run("eval")
print(r1, r1.label)
