def avg(nums):
    if not nums:
        return None
    return sum(nums) / len(nums)

print(avg([2, 4, 6]))
print(avg([]))
print(avg([]) is None)

def counted(fn):
    def inner(*args, **kwargs):
        inner.calls += 1
        return fn(*args, **kwargs)
    inner.calls = 0
    return inner

@counted
def square(n):
    return n * n

print(square(3), square.calls)
print(square(4), square.calls)

def collect(*args, **kwargs):
    return args, sorted(kwargs)

print(collect(1, 2, x=3, y=4))

