class ConfigError(Exception):
    """Raised when a required config key is missing."""

def load(config, *, require):
    for key in require:
        if key not in config:
            raise ConfigError(f"missing key: {key}")
    return {k: config[k] for k in require}

try:
    load({"model": "gpt"}, require=["model", "api_key"])
except ConfigError as e:
    print(type(e).__name__, e)
print(load({"model": "gpt", "api_key": "sk-x"}, require=["model"]))
print(issubclass(ConfigError, Exception))

